import{_ as t,o as a,c as i,ao as r}from"./chunks/framework.DagBLaYp.js";const m=JSON.parse('{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":null}'),s={name:"api.md"};function o(n,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="API-reference" tabindex="-1">API reference <a class="header-anchor" href="#API-reference" aria-label="Permalink to &quot;API reference {#API-reference}&quot;">​</a></h1><p>The API is grouped by the decisions users make. Start with the <a href="./api/simulation">simulation reference</a>, then use the page for the subsystem you are changing or composing.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Need</th><th style="text-align:right;">Reference</th></tr></thead><tbody><tr><td style="text-align:right;">build a model, set run conditions, simulate, inspect results</td><td style="text-align:right;"><a href="./api/simulation">Simulation and results</a></td></tr><tr><td style="text-align:right;">relax a constant autonomous MSMPR to steady state</td><td style="text-align:right;"><a href="./api/simulation">Simulation and results</a></td></tr><tr><td style="text-align:right;">set temperature or solubility</td><td style="text-align:right;"><a href="./api/conditions">Process conditions</a></td></tr><tr><td style="text-align:right;">choose or extend kinetic models</td><td style="text-align:right;"><a href="./api/kinetics">Kinetic models and rates</a></td></tr><tr><td style="text-align:right;">choose a solver or inspect quadrature</td><td style="text-align:right;"><a href="./api/solvers">Solvers and quadrature</a></td></tr><tr><td style="text-align:right;">load measurements or evaluate losses</td><td style="text-align:right;"><a href="./api/measurements">Measurements and losses</a></td></tr><tr><td style="text-align:right;">estimate parameters or propagate uncertainty</td><td style="text-align:right;"><a href="./api/inference">Inference and uncertainty</a></td></tr><tr><td style="text-align:right;">create plots or chain diagnostics</td><td style="text-align:right;"><a href="./api/plotting">Plotting and diagnostics</a></td></tr></tbody></table><h2 id="Named-kinetic-parameters" tabindex="-1">Named kinetic parameters <a class="header-anchor" href="#Named-kinetic-parameters" aria-label="Permalink to &quot;Named kinetic parameters {#Named-kinetic-parameters}&quot;">​</a></h2><p>Calling a law with all of its parameter names, e.g. <code>EmpiricalGrowth(growth_coefficient = 1e-9, growth_order = 2.0)</code>, returns a bound <code>KineticModel</code>; <code>KineticModel(law; parameters=(...))</code> is the long form. <code>OptimisationSpec.bounds</code>, <code>BayesianSpec.priors</code> and <code>ABCSpec.priors</code> select kinetic parameters using nested names such as <code>growth.growth_coefficient</code>. Unselected values stay fixed. <code>ParameterSamples</code> uses those same paths for joint uncertainty draws.</p><h2 id="Cross-cutting-contracts" tabindex="-1">Cross-cutting contracts <a class="header-anchor" href="#Cross-cutting-contracts" aria-label="Permalink to &quot;Cross-cutting contracts {#Cross-cutting-contracts}&quot;">​</a></h2><ul><li><p>Numeric SI: seconds, Kelvin, kg/m³, metres, rates in m/s.</p></li><li><p><code>simulate(model, conditions; solver, saveat)</code> returns the physical solution; <code>runsimulation</code> is the low-level interface for autodiff and sensitivity work.</p></li><li><p><code>RunConditions</code> hold temperature, initial concentration and solvent values, the seed and the operation; <code>FromObservation</code> reads a value from time-zero data.</p></li><li><p><code>Observable</code> is a time series, including one-point measurements.</p></li><li><p>Transient fitting resolves <code>FromObservation</code> conditions from time-zero observations; those samples are not scored.</p></li><li><p>Likelihood requires supplied positive scored variances; noise is never fitted.</p></li><li><p>Fits return a new model and retain native backend diagnostics.</p></li><li><p><code>predict(result)</code> reuses the fit&#39;s solver, mode and options; predicting from user samples requires an explicit <code>solver</code>.</p></li><li><p>Predictions retain failed draws; exclusion from summaries is explicit.</p></li><li><p>ForwardDiff and finite differences are tested; reverse Enzyme remains deferred.</p></li></ul><p>The lower-level solver engine still uses the internal block order nucleation, growth, dissolution, aggregation, breakage. Named model users do not assemble those vectors. Generated SciML and dispatch-based extension interfaces remain available for advanced users.</p><p>Custom nucleation families may subtype <code>CriSTool.AbstractNucleationFunction</code> by qualification/import; that base is not currently exported. The standard custom-rate signature is <code>(fn, parameters, problem, state, t)</code>.</p>',9)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
